def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    old_char = board[row][col]
    new_char = 'g' if old_char == 'N' else 'N'

    # Move 'N' down
    for i in range(row+1, 64):
        if board[i][col] == 'N':
            board[i][col] = 'g'
            break

    # Recolour 'g' to 'N'
    for i in range(row, 64):
        if board[i][col] == 'g':
            board[i][col] = 'N'
            break

    # Handle edge case where 'g' is at the bottom row
    if row > 0 and board[row-1][col] == 'g':
        board[row-1][col] = 'N'

    # Handle edge case where 'N' is at the top row
    if row < 63 and board[row+1][col] == 'N':
        board[row+1][col] = 'g'

    # Update the board
    for i in range(64):
        if i == row:
            board[i] = board[i][:col] + new_char + board[i][col+1:]
        else:
            board[i] = board[i].replace(old_char, new_char)

    return board
